style.css:
css
/* Bubblegum Dream — TikTok */

:root {
  /* swap these colors if you want */
  --my-pink: #ff85c2;
  --my-pink-light: #ffb6dc;
}

/* bubblegum pink background */
html,
body {
  background: var(--my-pink) !important;
}

/* keep the pink going through the page */
body {
  background-color: var(--my-pink) !important;
  background-image: linear-gradient(
    135deg,
    #ff85c2,
    #ffacd6,
    #ffc4e5
  ) !important;
  background-attachment: fixed !important;
}
